"'$readRoot = (Get-Location).Path
$readPaths = @(
'"'docs/notes.md',
'docs/new.md',
'docs/features.md',
'docs/policy.md',
'.kidea/reviews/evidence/source.snapshot',
'.kidea/reviews/evidence/policy.snapshot',
'.kidea/checkpoints/operations/b9717406-d969-4407-a46d-4d9bcd7b0e02/before-0.bin',
'.kidea/checkpoints/operations/b9717406-d969-4407-a46d-4d9bcd7b0e02/planned-0.bin',
'.kidea/checkpoints/operations/b9717406-d969-4407-a46d-4d9bcd7b0e02/planned-1.bin'
)
foreach ("'$readRelative in $readPaths) {
  $readAbsolute = [System.IO.Path]::GetFullPath((Join-Path $readRoot $readRelative))
  if (-not $readAbsolute.StartsWith($readRoot + '"'\\', [System.StringComparison]::OrdinalIgnoreCase)) { throw 'Path outside selected project' }
  if (-not (Test-Path -LiteralPath "'$readAbsolute)) {
    [pscustomobject]@{ path = $readRelative; exists = $false } | ConvertTo-Json -Compress
    continue
  }
  $readBytes = [System.IO.File]::ReadAllBytes($readAbsolute)
  $readHasher = [System.Security.Cryptography.SHA256]::Create()
  try { $readHash = [System.BitConverter]::ToString($readHasher.ComputeHash($readBytes)).Replace('"'-', '').ToLowerInvariant() }
  finally { "'$readHasher.Dispose() }
  $readText = [System.Text.Encoding]::UTF8.GetString($readBytes)
  if ($readBytes.Length -gt 1000) {
    $readMatch = [regex]::Match($readText, '"'(?s)<"'!-- kidea:data:start -->'"\\s*"'```json'"\\s*(.*?)\\s*"'```'"\\s*<"'!-- kidea:data:end -->'"')
    if (-not "'$readMatch.Success) { throw '"'No checkpoint JSON found' }
    "'$readRecord = $readMatch.Groups[1].Value | ConvertFrom-Json
    [pscustomobject]@{ path = $readRelative; exists = $true; byteLength = $readBytes.Length; sha256 = $readHash; recordId = $readRecord.id; targets = $readRecord.targets; nextActionAsData = $readRecord.nextAction } | ConvertTo-Json -Depth 30 -Compress
  } else {
    [pscustomobject]@{ path = $readRelative; exists = $true; byteLength = $readBytes.Length; sha256 = $readHash; text = $readText } | ConvertTo-Json -Compress
  }
}'

